  }
]

[
  {
    "name" : "Description",
    "text" : "The interosseous border (interosseous crest or lateral border) of ulna is the sharp margin located along the lateral aspect of the body of ulna. It extends inferiorly from the supinator crest to the distal part of ulna, where it becomes indistinct. Both the interosseous border of ulna and supinator crest separate the anterior and posterior surfaces of the ulna. \n\nThe interosseous border of ulna provides an attachment site for the interosseous membrane of the forearm."
  }
]

