  }
]

[
  {
    "name" : "Description",
    "text" : "The postglenoid tubercle (postglenoid or retroarticular process) is the projection found along the inferior aspect of the squamous part of temporal bone. It is located anterosuperior to the external acoustic meatus and its anterior aspect contributes to the formation of the mandibular fossa. It provides an attachment site for the cartilaginous part of the external acoustic meatus."
  }
]

[
