  }
]

[
  {
    "name" : "Quick Facts",
    "text" : "The pyramidal process of the palatine bone extends posteriorly from the junction of the horizontal and perpendicular plates. It joins the medial and lateral pterygoid plates of the sphenoid bone."
  }
]

